<?php
$root=$argv[1];$stage=$argv[2];require $root.'/vendor/autoload.php';$app=require $root.'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\{DB,Schema,Queue,Mail,Http};use Illuminate\Database\Schema\Blueprint;use App\Models\{Pdv,User,TagPurchase,Vehicle};
config(['database.default'=>'commission_memory','database.connections.commission_memory'=>['driver'=>'sqlite','database'=>':memory:','prefix'=>'','foreign_key_constraints'=>true],'cache.default'=>'array']);DB::setDefaultConnection('commission_memory');if(DB::connection()->getDriverName()!=='sqlite'||DB::connection()->getDatabaseName()!==':memory:')throw new RuntimeException('Memory-only guard');Queue::fake();Mail::fake();Http::preventStrayRequests();
foreach(['PdvSalesService','AdminService','AdminPdvService'] as $name)require $stage.'/app/Services/'.$name.'.php';
Schema::create('points_of_sale',function(Blueprint $t){$t->id();$t->string('name');$t->decimal('commission_percentage',5,2)->nullable();$t->softDeletes();$t->timestamps();});
Schema::create('users',function(Blueprint $t){$t->id();foreach(['name','email','phone'] as $c)$t->string($c)->nullable();foreach(['type','pdv_id','user_id_admin_pdv'] as $c)$t->integer($c)->nullable();$t->softDeletes();$t->timestamps();});
Schema::create('vehicles',function(Blueprint $t){$t->id();$t->integer('user_id');foreach(['plate','name','color','year'] as $c)$t->string($c)->nullable();$t->softDeletes();$t->timestamps();});
Schema::create('tags',function(Blueprint $t){$t->id();$t->string('name')->nullable();$t->string('slug')->nullable();$t->softDeletes();$t->timestamps();});
Schema::create('shipments',function(Blueprint $t){$t->id();$t->integer('tag_purchase_id');$t->integer('status')->default(0);$t->softDeletes();$t->timestamps();});
Schema::create((new TagPurchase)->getTable(),function(Blueprint $t){$t->id();foreach(['user_id','vehicle_id','tag_id','qty','status'] as $c)$t->integer($c)->nullable();foreach(['mp_payment_status','mp_payment_id','payment_method','coupon_info','pickup_point','delivery'] as $c)$t->text($c)->nullable();foreach(['price','price_total','shipping_price'] as $c)$t->decimal($c,10,2)->nullable();$t->softDeletes();$t->timestamps();});
$n=0;$ok=function($v,$label)use(&$n){if(!$v)throw new RuntimeException($label);$n++;};$near=function($a,$b)use($ok){$ok(abs($a-$b)<.001,'unexpected money value');};
$a=Pdv::create(['name'=>'Point A','commission_percentage'=>20]);$b=Pdv::create(['name'=>'Point B','commission_percentage'=>10]);$empty=Pdv::create(['name'=>'Empty']);
$staffA=User::create(['name'=>'Staff A','type'=>2,'pdv_id'=>$a->id]);$staffA2=User::create(['name'=>'Staff A2','type'=>2,'pdv_id'=>$a->id]);$staffB=User::create(['name'=>'Staff B','type'=>2,'pdv_id'=>$b->id]);
$online=User::create(['name'=>'Online customer','email'=>'private@example.test','phone'=>'hidden','type'=>3]);$owned=User::create(['name'=>'Origin A customer','type'=>3,'user_id_admin_pdv'=>$staffA->id]);$other=User::create(['name'=>'Other customer','type'=>3,'user_id_admin_pdv'=>$staffB->id]);
$v=Vehicle::create(['user_id'=>$online->id,'plate'=>'ABC1D23']);$v2=Vehicle::create(['user_id'=>$owned->id,'plate'=>'ABC1D24']);$v3=Vehicle::create(['user_id'=>$other->id,'plate'=>'ABC1D25']);
$make=function($u,$vehicle,$point,$price,$qty,$paid,$status='approved',$delivery=null) {return TagPurchase::create(['user_id'=>$u->id,'vehicle_id'=>$vehicle->id,'pickup_point'=>$point,'delivery'=>$delivery,'price'=>$price,'qty'=>$qty,'price_total'=>$paid,'shipping_price'=>50,'mp_payment_status'=>$status,'mp_payment_id'=>'qa-'.uniqid(),'status'=>1,'payment_method'=>'pix']);};
$free=$make($online,$v,['id'=>$a->id],29.90,1,0);$report=new App\Services\PdvSalesService;
$t=$report->totals($a);$near($t['commission_base_amount'],29.90);$near($t['commission_amount'],5.98);$near($t['total_sales_amount'],0);$ok($t['total_sales_qty']===1,'free kit counted');
$partial=$make($online,$v,['id'=>(string)$a->id],29.90,2,29.90);$t=$report->totals($a);$near($t['commission_amount'],17.94);$ok($t['total_sales_qty']===3,'quantity and string point id');$near($t['commission_base_amount'],89.70);
$origin=$make($owned,$v2,null,29.90,1,29.90,'approved',['street'=>'Example']);$switch=$make($owned,$v2,['id'=>$b->id],29.90,1,0);$t=$report->totals($a);$near($t['commission_amount'],23.92);$near($report->totals($b)['commission_amount'],2.99);$ok($report->attributedTo($a)->whereKey($switch->id)->count()===0,'pickup has priority, no double commission');
foreach(['pending','rejected','cancelled','refunded','charged_back'] as $status)$make($online,$v,['id'=>$a->id],100,1,100,$status);
$deleted=$make($online,$v,['id'=>$a->id],100,1,100);$deleted->delete();$make($other,$v3,null,10,1,10);
$t=$report->totals($a);$near($t['commission_amount'],23.92);$near($t['total_sales_amount'],59.80);$ok($t['total_sales_qty']===4,'only approved and nondeleted counted');$near($report->totals($empty)['commission_amount'],0);
$near($report->totals($a,now()->addDay(),null)['commission_amount'],0);$near($report->totals($a,null,now()->subDay())['commission_amount'],0);
$admin=new App\Services\AdminService;$rows=$admin->pdvCommissions(null,null,null,null,100)->getCollection()->keyBy('pdv_id');$near($rows[$a->id]['commission_amount'],23.92);$near($rows[$b->id]['commission_amount'],3.99);$ok($rows[$a->id]['total_sales_qty']===4,'owner and dashboard same quantity');$ok($rows[$a->id]['staff_count']===2,'multiple staff no duplicate');$near($rows[$a->id]['commission_base_amount'],119.60);
$ok($admin->pdvCommissions(null,null,$staffA2->id,null,100)->total()===1,'filter maps access to point');$ok($admin->pdvCommissions(null,null,null,'Point B',100)->total()===1,'search preserved');
foreach([$staffA,$staffA2] as $staff){$d=(new App\Services\AdminPdvService)->dashboard($staff,now()->toDateString(),now()->toDateString());$near($d['totals']['commission_amount'],23.92);$near($d['totals']['revenue'],59.80);$near($d['totals']['commission_base_amount'],119.60);$ok($d['totals']['orders']>=2,'online pickup orders in dashboard');$ok($d['totals']['users']>=1,'online customer counted');$ok($d['totals']['vehicles']>=1,'online vehicle counted');$ok($d['latest_orders']->contains('id',$free->id),'online order in recent list');$onlineRow=$d['latest_users']->firstWhere('id',$online->id);$ok($onlineRow&&$onlineRow->email===null&&$onlineRow->phone===null,'no extra private contact details exposed');}
$a->update(['commission_percentage'=>0]);$near($report->totals($a)['commission_amount'],0);$a->update(['commission_percentage'=>100]);$near($report->totals($a)['commission_amount'],119.60);$a->update(['commission_percentage'=>null]);$near($report->totals($a)['commission_amount'],0);
$pdvService=new App\Services\AdminPdvService;$before=User::count();
foreach(['createUser','updateUser','deleteUser'] as $method){try{if($method==='createUser')$pdvService->$method($staffA,['name'=>'Forbidden']);elseif($method==='updateUser')$pdvService->$method($staffA,$owned->id,['name'=>'Forbidden']);else $pdvService->$method($staffA,$owned->id);throw new RuntimeException('Mutation unexpectedly allowed');}catch(Illuminate\Validation\ValidationException $e){$ok(str_contains($e->getMessage(),'consulta'),'PDV user mutation blocked');}}
$ok(User::count()===$before&&$owned->fresh()->name==='Origin A customer','readonly mutation changed no records');
$consult=$pdvService->users($staffA)->getCollection();$ok($consult->contains('id',$online->id),'online pickup customer consultable');$ok(!$consult->contains('id',$other->id),'unrelated customer hidden');$check=$consult->firstWhere('id',$online->id);$ok($check->email===null&&$check->phone===null,'consultation redacts unrelated contact fields');$ok($pdvService->userTotals($staffA)['active']===2,'consultation totals match scope');
echo 'PASS '.$n.' commission/dashboard checks; SQLite memory only, no payments, mail or production writes.'.PHP_EOL;
